import { createElement, RawHTML, useRef, useState } from '@wordpress/element';
import { __, sprintf } from '@wordpress/i18n';
import { Button } from '@wordpress/components';
import { questionPreviewModel } from './questionBlocks.mjs';

/** Interactive learner appearance, built from the current unsaved question rather than a preview page. */
export function QuestionLivePreview({ question }) {
  const view = questionPreviewModel(question);
  const group = useRef(`question-preview-${Math.random().toString(36).slice(2)}`);
  const [order, setOrder] = useState(() => [...view.options].reverse());
  const move = (index, direction) =>
    setOrder((old) => {
      const next = [...old];
      [next[index], next[index + direction]] = [next[index + direction], next[index]];
      return next;
    });
  const answerInput = (label, multiline = false) => (
    <label className="ohmylms-preview-input">
      {label}
      {multiline ? (
        <textarea
          aria-label={label}
          rows={4}
          placeholder={__('Type your answer here ...', 'ohmylms')}
        />
      ) : (
        <input
          aria-label={label}
          type="text"
          placeholder={__('Type your answer here ...', 'ohmylms')}
        />
      )}
    </label>
  );
  return (
    <section
      className="ohmylms-question-live-preview"
      aria-label={__('Question preview', 'ohmylms')}
    >
      <p className="ohmylms-preview-note">
        {__('Learner preview · responses here are not saved or graded.', 'ohmylms')}
      </p>
      <h3>
        {view.title.map((part, index) =>
          part.blank ? (
            <input
              key={index}
              aria-label={sprintf(__('Blank %d', 'ohmylms'), index + 1)}
              className="ohmylms-preview-blank"
            />
          ) : (
            <span key={index}>{part.text}</span>
          ),
        )}
      </h3>
      <RawHTML>{view.body}</RawHTML>
      {['single-choice', 'multiple-choice', 'true-false'].includes(view.type) &&
        view.options.map((option) => (
          <label key={option.id} className="ohmylms-preview-choice">
            <input
              type={view.type === 'multiple-choice' ? 'checkbox' : 'radio'}
              name={group.current}
              value={option.id}
            />
            {option.answer || __('Answer option', 'ohmylms')}
          </label>
        ))}
      {['short-text', 'statement', 'numerical'].includes(view.type) &&
        answerInput(
          view.type === 'numerical' ? __('Number', 'ohmylms') : __('Your answer', 'ohmylms'),
        )}
      {view.type === 'numerical' && view.unit && <span>{view.unit}</span>}
      {view.type === 'long-text' && answerInput(__('Your answer', 'ohmylms'), true)}
      {view.type === 'fill-in-the-blank' &&
        !view.title.some((part) => part.blank) &&
        answerInput(__('Your answer', 'ohmylms'))}
      {view.type === 'matching' &&
        view.options.map((option) => (
          <label className="ohmylms-preview-choice" key={option.id}>
            {option.answer}
            <select
              aria-label={sprintf(__('Match for %s', 'ohmylms'), option.answer)}
              defaultValue=""
            >
              <option value="">{__('Choose a match', 'ohmylms')}</option>
              {[...view.options].reverse().map((match) => (
                <option key={match.id} value={match.id}>
                  {match.match}
                </option>
              ))}
            </select>
          </label>
        ))}
      {view.type === 'reorder' && (
        <ol>
          {order.map((option, index) => (
            <li key={option.id}>
              {option.answer}
              <Button disabled={index === 0} onClick={() => move(index, -1)}>
                {__('Move up', 'ohmylms')}
              </Button>
              <Button disabled={index === order.length - 1} onClick={() => move(index, 1)}>
                {__('Move down', 'ohmylms')}
              </Button>
            </li>
          ))}
        </ol>
      )}
      {view.type === 'structured' &&
        view.parts.map((part) => (
          <fieldset key={part.id}>
            <legend>
              {part.label} · {part.marks} {__('marks', 'ohmylms')}
            </legend>
            <p>{part.prompt}</p>
            {answerInput(
              sprintf(__('Part %s answer', 'ohmylms'), part.label),
              part.kind === 'written',
            )}
          </fieldset>
        ))}
    </section>
  );
}
